{
  "PROP-56ad1eb2-inv-027": {
    "property_id": "PROP-56ad1eb2-inv-027",
    "audit_result": {
      "property_id": "PROP-56ad1eb2-inv-027",
      "classification": "vulnerability",
      "code_path": "beacon-chain/core/signing/signing_root.go::ComputeForkDigest::L304-310",
      "proof_trace": "ComputeForkDigest only uses fork_version and genesis_validators_root (lines 304-310), ignoring blob parameters entirely. For Fulu (EIP-7892), fork digests must incorporate blob params via XOR with hash(epoch||max_blobs). The network schedule correctly implements this (config.go:576-590), but ComputeForkDigest bypasses it. When bootnode or other code paths call ComputeForkDigest directly for Fulu, networks with same fork_version but different blob params produce identical digests, breaking network isolation.",
      "attack_scenario": "Attacker configures bootnode for Fulu fork with different MaxBlobsPerBlock than the legitimate network but same ForkVersion. ComputeForkDigest (bootnode.go:221) produces identical fork digest. Victim nodes connect to attacker's network thinking it's the same chain, leading to consensus failures, incompatible block processing, and potential chain split.",
      "checklist_id": "PROP-56ad1eb2-inv-027"
    },
    "text": "Fork digest must differ when blob parameters change, even if fork version is unchanged (EIP-7892).",
    "assertion": "forall e1,e2: blob_params(e1)!=blob_params(e2) => fork_digest(e1)!=fork_digest(e2)",
    "covers": "SG-003",
    "severity": "HIGH",
    "type": "invariant"
  }
}

// Spec pseudocode definition:
//
//		def compute_fork_digest(current_version: Version, genesis_validators_root: Root) -> ForkDigest:
//	   """
//	   Return the 4-byte fork digest for the ``current_version`` and ``genesis_validators_root``.
//	   This is a digest primarily used for domain separation on the p2p layer.
//	   4-bytes suffices for practical separation of forks/chains.
//	   """
//	   return ForkDigest(compute_fork_data_root(current_version, genesis_validators_root)[:4])
func ComputeForkDigest(version, genesisValidatorsRoot []byte) ([4]byte, error) {
	dataRoot, err := computeForkDataRoot(version, genesisValidatorsRoot)
	if err != nil {
		return [4]byte{}, err
	}
	return bytesutil.ToBytes4(dataRoot[:]), nil
}

